import React, { useState } from 'react';
import './Chip.css';

export function Chip({
  Size = 'M',
  Icon = false,
  Label = 'Filter',
  ...props
}) {
  const [pressed, setPressed] = useState(false);

  const handleClick = () => {
    setPressed(!pressed);
  };

  const sizeClass = Size === 'L' ? 'chip--l' : '';

  return (
    <button
      type="button"
      role="button"
      aria-pressed={pressed}
      className={`chip ${sizeClass}`.trim()}
      onClick={handleClick}
      {...props}
    >
      {Icon && <span className="chip-icon">☐</span>}
      <span className="chip-label">{Label}</span>
    </button>
  );
}

