files.src/components/Tag.jsx:
export default function Tag({ className, Label = "New", Tone = "Neutral" }) {
  const baseClass = "tag";
  const toneClass = Tone === "Positive" ? "tag--positive" : "";
  const finalClass = [baseClass, toneClass, className].filter(Boolean).join(" ");

  return (
    <div className={finalClass}>
      {Label}
    </div>
  );
}

