export default function Tag({ Label = "New", Tone = "Neutral" }) {
  const classes = ["tag"];
  if (Tone === "Positive") {
    classes.push("tag--positive");
  }

  return (
    <div className={classes.join(" ")}>
      {Label}
    </div>
  );
}

