export default function Tag({ className, Label = "New", Tone = "Neutral" }) {
  const isPositive = Tone === "Positive";
  const classes = className
    ? className
    : `tag ${isPositive ? "tag--positive" : ""}`.trim();

  return (
    <div className={classes}>
      {Label}
    </div>
  );
}

